#!/usr/bin/env python3
"""Is every shipped artifact generated by the pipeline, or did some arrive by hand?

Six classes of artifact go out with the submission -- input data, metadata
tables, figure data objects, figures, result tables, and the HTML companions --
and the claim being made is that all of them come from running the code. That
claim is easy to assert and easy to break: a table hand-edited once, a figure
saved from a notebook, an HTML page built from a file that has since moved.

So this asks, per artifact: does it exist, does something in the tree write it,
is it newer than the code that writes it, and -- for figures -- does it publish
a data object and redraw from it. Producers are found by searching the code for
the filename the artifact is written under, which is why the report names the
producing file rather than asserting provenance in the abstract.

"ORPHAN" means present but with no producer found. That is the finding worth
acting on: either the artifact is stale and should be deleted, or it is real
and its producer needs committing.

    python tools/audit_artifact_provenance.py
    python tools/audit_artifact_provenance.py --class figures
"""
from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

CODE_DIRS = ("persistence", "figures", "tools")
_CODE: dict[Path, str] = {}


def code_text() -> dict[Path, str]:
    """Every .py in the tree, read once."""
    if not _CODE:
        for d in CODE_DIRS:
            for f in (ROOT / d).rglob("*.py"):
                try:
                    _CODE[f] = f.read_text()
                except OSError:
                    pass
    return _CODE


#: Producers that the tree already declares, rather than ones inferred from
#: the text of the code. An earlier version of this file searched the source
#: for each artifact's filename, shortening the stem until something matched.
#: It produced confident nonsense in both directions -- `figure1` was too
#: short to match anything and came back ORPHAN, while `pipeline_audit_090726`
#: shortened to `pipeline` and matched ninety-seven files. Guessed provenance
#: is worse than absent provenance, so this now reports only what a registry
#: states, and says "unknown" otherwise.
DECLARED = {
    # tables, from the function that writes them
    "health_richness_gmw": "persistence/section3_health.py"
                           " :: _run_richness_comparison",
    "health_per_taxon_gmw": "persistence/section3_health.py"
                            " :: _run_per_taxon_gmw",
    "health_per_taxon_prevmatched": "persistence/section3_health.py"
                                    " :: _run_prevalence_matched_background",
    "demographic_richness_gmw": "persistence/section3_health.py"
                                " :: _run_richness_comparison(demographic)",
    "demographic_per_taxon_gmw": "persistence/section3_health.py"
                                 " :: _run_per_taxon_gmw(demographic)",
    "demographic_per_taxon_prevmatched":
        "persistence/section3_health.py"
        " :: _run_prevalence_matched_background(demographic)",
    "demographic_cohorts": "persistence/section3_health.py"
                           " :: _write_demographic_cohorts",
    "demographic_field_coverage": "persistence/section3_health.py"
                                  " :: _write_demographic_cohorts",
    "demographic_table_s10a": "persistence/table_s7.py :: write_table_s7",
    "demographic_table_s10b": "persistence/table_s7.py :: write_table_s7",
    # metadata
    "metadata_M1": "tools/build_curated_m1.py + tools/correct_metadata_final.py",
    "metadata_M2": "tools/build_metadata_tables.py",
    "metadata_M3": "tools/build_metadata_tables.py",
    # html companions with a generator
    "final_run_plan": "tools/preflight_final_run.py",
    "health_definition_rerun_plan": "tools/build_health_rerun_plan.py",
    "masld_rename_implementation": "tools/build_masld_checklist.py",
    "supplementary_figures": "tools/build_supp_review.py",
    "taxonomy_update_checklist": "tools/build_taxonomy_checklist.py",
    "figure_review": "tools/build_figure_review.py",
    "figure_ab": "tools/figure_ab_probe.py",
    "metadata_explorer": "tools/metadata_explorer/build_explorer.py",
    "science_compliance": "tools/audit_science_specs.py",
    "metadata_profile": "tools/profile_metadata.py",
    # The journal-required figure source data, and the Word rendering of Table
    # S12. Declared so they count as submission artifacts with named producers
    # rather than being invisible here: both are built by standalone tools
    # *after* the run, not by `python -m persistence`, and a post-run step
    # with nothing watching it is exactly what gets skipped between a run and
    # a deposit.
    "Data_S1_figure_data": "tools/build_data_s1.py + tools/data_s1_extras.py",
    "Table_S12": "tools/build_table_s12_docx.py",
}


#: Documents written by hand, not emitted by the pipeline. Declaring them
#: keeps "ORPHAN" meaning "should have a producer and does not", which is the
#: finding worth acting on. Everything here is prose about the work -- notes,
#: guides, letters, page templates -- and a deposit should describe them as
#: authored rather than imply the code generated them.
AUTHORED = {
    "_figure_ab_template", "_figure_inspector_template",
    "blossum_health_softening_091026", "consistency_implementation",
    "a cover-letter draft", "a cover-letter draft",
    "figure4_reconciliation_090926", "figure_inspector",
    "figure_lessons_a13", "figure_sources_090926",
    "implementation_090926", "pipeline_audit_090726",
    "a revision guide", "a revision guide", "a revision guide",
    "submission_checklist", "supp_note1_s2b_s3_rebuild",
}


def producers(name: str) -> list[str]:
    """The declared producer, or [] if the tree does not state one."""
    stem = re.sub(r"\.(csv|png|pdf|pkl|html|xlsx|tsv|txt)$", "", name)
    if stem in AUTHORED:
        return ["(authored by hand, not generated)"]
    for key, who in DECLARED.items():
        if stem.startswith(key):
            return [who]
    return []


def newest_code_mtime(paths: list[str]) -> float:
    """Newest mtime among the declared producers.

    A declaration may name a function ("module.py :: func") or a pipeline
    stage ("--only s3") rather than a file, so anything that does not resolve
    to a real path is skipped instead of raising.
    """
    mts = []
    for p in paths:
        for part in str(p).split(" + "):
            f = ROOT / part.split(" :: ")[0].strip()
            if f.is_file():
                mts.append(f.stat().st_mtime)
    return max(mts, default=0.0)


def row(cls, artifact, path, note=""):
    p = ROOT / path
    exists = p.exists()
    prod = producers(Path(path).name) if exists else []
    stale = None
    if exists and prod:
        stale = p.stat().st_mtime < newest_code_mtime(prod)
    return dict(cls=cls, artifact=artifact, path=path, exists=exists,
                producers=prod, stale=stale, note=note)


# Which modules draw each figure directory's figures. Used to answer the
# staleness question; a figure older than any of these was left by an earlier
# run and does not reflect the code in the tree.
FIGURE_CODE = {
    "section1_diversity":  ["persistence/section1_diversity.py"],
    "section2_differential": ["persistence/differential.py"],
    "section3_health":     ["persistence/section3_health.py",
                            "persistence/health_background.py"],
    "carter_analysis":     ["persistence/carter_analysis.py"],
    "depth_audit":         ["persistence/depth_audit.py"],
    "depth_bias_ipw":      ["persistence/depth_bias_ipw.py"],
}
# Drawn through by essentially every figure, so a change here dates all of them.
SHARED_FIGURE_CODE = ["persistence/plot_utils.py"]


def collect_figures():
    """Every manifest slot plus the five main-text figures."""
    from tools import figure_sets
    from persistence import figure_source

    from persistence import figure_runner
    import importlib
    replot = importlib.import_module("tools.replot_from_data")

    # Which section rebuilds each figure directory, and which slots redraw
    # from their own data object. Both come from the tree's own registries:
    # the manifest for slot -> output, replot_from_data.DRAW for slot ->
    # redraw, figure_runner.TASKS for main figure -> script.
    section_of = {"section1_diversity": "--only s1",
                  "section2_differential": "--only s2",
                  "section3_health": "--only s3",
                  "carter_analysis": "--only carter",
                  "depth_audit": "(always runs)",
                  "depth_bias_ipw": "--only depth_bias",
                  "figure_s0_roadmap": "--figure roadmap"}
    rows = []
    for slot, ref, stem in figure_sets.manifest():
        png = f"results/{ref}/{stem}.png"
        r = row("figures", slot, png)
        top = stem.split("/")[0]
        who = section_of.get(top)
        if who is None:
            who = "--figure accum/figure3" if ("accum" in top or
                                               "figure3" in top) else ""
        # Staleness IS answerable for a figure: compare it against the
        # modules that draw it. Setting it to None meant the tool's headline
        # question -- is this artefact older than the code that writes it --
        # was never answered for a single figure, which is the exact failure
        # this repository has already fixed twice.
        code = FIGURE_CODE.get(top, []) + SHARED_FIGURE_CODE
        r["producers"] = ([who] if who else []) + code
        r["stale"] = (None if not r["exists"] or not code
                      else (ROOT / png).stat().st_mtime
                      < newest_code_mtime(code))
        d = (ROOT / f"results/{ref}/{Path(stem).parent}"
             / "figure_data" / f"Figure_{slot}_data.pkl")
        r["data_object"] = d.exists()
        r["redraws"] = slot in replot.DRAW
        rows.append(r)
    for n in range(1, 6):
        r = row("figures", f"F{n}", f"main_text_figures/figure{n}.png")
        t = figure_runner.TASKS.get(f"figure{n}")
        code = ([f"figures/{t.script}"] if t else []) + SHARED_FIGURE_CODE
        r["producers"] = code
        _p = ROOT / f"main_text_figures/figure{n}.png"
        r["stale"] = (None if not _p.exists() or not code
                      else _p.stat().st_mtime < newest_code_mtime(code))
        d = ROOT / f"main_text_figures/figure_data/Figure_F{n}_data.pkl"
        r["data_object"] = d.exists()
        # Read the registry rather than assert it. "DRAW covers F1-F5" was
        # true when written and nothing checked it afterwards.
        try:
            r["redraws"] = f"F{n}" in importlib.import_module(
                "tools.replot_main").DRAW
        except Exception:
            r["redraws"] = False
        rows.append(r)
    return rows


def collect_rest():
    from persistence import config

    rows = []
    # ── inputs: external by design, linked in rather than produced ──
    for m in sorted(Path(ROOT).glob("combined_*_matrix_*.csv")):
        r = row("data", m.name, m.name,
                "external input; linked by setup_symlinks.sh")
        r["producers"] = r["producers"] or ["(external)"]
        r["stale"] = None
        rows.append(r)
    rows.append(row("metadata", "M1 (curated)", config.META_FILE))
    for f in ("metadata_M2.xlsx", "metadata_M3.xlsx"):
        rows.append(row("metadata", Path(f).name, f))

    # ── result tables the figures and manuscript quote ──
    s3 = "results/combined/section3_health/main"
    for f in ("health_richness_gmw_10pct.csv", "health_per_taxon_gmw_10pct.csv",
              "health_per_taxon_prevmatched_10pct.csv",
              "demographic_richness_gmw_10pct.csv",
              "demographic_per_taxon_gmw_10pct.csv",
              "demographic_per_taxon_prevmatched_10pct.csv",
              "demographic_cohorts.csv", "demographic_field_coverage.csv",
              "demographic_table_s10a_unadjusted_10pct.csv",
              "demographic_table_s10b_energy_first_10pct.csv"):
        rows.append(row("tables", f, f"{s3}/{f}"))

    # ── the flat supplementary view ──
    # supplementary_figures/ is symlinks into results/, rebuilt by
    # tools/link_supplementary_figures.py. It is what a reader is handed, so a
    # slot missing from it is invisible to them even though the figure exists:
    # S32 was absent from it for a day after the figure was first drawn.
    from tools import figure_sets
    flat = ROOT / "supplementary_figures"
    slots = [s for s, _r, _st in figure_sets.manifest()]
    if flat.is_dir():
        have = {f.name.split("_")[0] for f in flat.glob("*.png")}
        havep = {f.name.split("_")[0] for f in
                 (flat / "figure_data").glob("*.pkl")} \
            if (flat / "figure_data").is_dir() else set()
        for want, label in ((have, "png"), (havep, "pkl")):
            missing = [s for s in slots
                       if s not in want and f"S{int(s[1:]):02d}" not in want]
            rows.append(dict(
                cls="flat view", artifact=f"all {len(slots)} slots ({label})",
                path="supplementary_figures", exists=not missing,
                producers=["tools/link_supplementary_figures.py"],
                stale=None,
                note="" if not missing else f"missing {missing}"))
        dangling = [f.name for f in list(flat.glob("*.png"))
                    + list((flat / "figure_data").glob("*.pkl"))
                    if not f.resolve().exists()]
        rows.append(dict(cls="flat view", artifact="no dangling symlinks",
                         path="supplementary_figures",
                         exists=not dangling,
                         producers=["tools/link_supplementary_figures.py"],
                         stale=None,
                         note="" if not dangling else f"{len(dangling)} broken"))

    # ── HTML companions ──
    for f in sorted(Path(ROOT / "docs").glob("*.html")):
        rows.append(row("html", f.name, f"docs/{f.name}"))
    rows.append(row("html", "metadata_explorer.html",
                    "tools/metadata_explorer/metadata_explorer.html"))
    return rows


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--class", dest="cls", default=None)
    ap.add_argument("--verbose", action="store_true")
    a = ap.parse_args()

    rows = collect_figures() + collect_rest()
    if a.cls:
        rows = [r for r in rows if r["cls"] == a.cls]

    orphans, missing, stale, no_data, no_redraw = [], [], [], [], []
    authored = []
    cur = None
    for r in rows:
        if r["cls"] != cur:
            print(f"\n  ── {r['cls']} " + "─" * (58 - len(r['cls'])))
            cur = r["cls"]
        if not r["exists"]:
            flag, missing_ = "MISSING", missing.append(r["artifact"])
        elif r["producers"] == ["(authored by hand, not generated)"]:
            flag = "authored"
            authored.append(r["artifact"])
        elif not r["producers"]:
            flag, _ = "ORPHAN", orphans.append(r["artifact"])
        elif r["stale"]:
            flag, _ = "stale", stale.append(r["artifact"])
        else:
            flag = "ok"
        extra = ""
        if "data_object" in r:
            extra = ("  pkl " + ("yes" if r["data_object"] else "NO ")
                     + "  redraw " + ("yes" if r.get("redraws") else "NO "))
            if not r["data_object"]:
                no_data.append(r["artifact"])
            if not r.get("redraws"):
                no_redraw.append(r["artifact"])
        src = (r["producers"][0] if r["producers"] else "-")
        if len(r["producers"]) > 1:
            src += f" +{len(r['producers'])-1}"
        _note = r.get("note") or ""
        print(f"  {flag:<8}{r['artifact']:<34}{extra:<26}  {src}"
              + (f"  {_note}" if _note else ""))

    print("\n  ── summary " + "─" * 52)
    print(f"  {len(rows)} artifacts checked")
    for label, lst in (("missing", missing), ("no producer found", orphans),
                       ("authored by hand (not a defect)", authored),
                       ("older than their producer", stale),
                       ("figures without a data object", no_data),
                       ("figures that cannot redraw from it", no_redraw)):
        print(f"    {label:<36}{len(lst)}"
              + (f"   {', '.join(lst[:6])}" if lst else ""))
    return 1 if (missing or orphans or no_data) else 0


if __name__ == "__main__":
    sys.exit(main())
